<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useCartStore } from '../stores/cart.js'
import { useCheckoutStore } from '../stores/checkout.js'
import { money, availabilityText } from '../utils/format.js'
import Icon from '../components/Icon.vue'
import ItemArt from '../components/ItemArt.vue'
import QuantityInput from '../components/QuantityInput.vue'
import StatePanel from '../components/StatePanel.vue'
const cart = useCartStore(), checkout = useCheckoutStore(), router = useRouter(), loading = ref(true), error = ref(null), busy = ref(false)
const all = computed(() => cart.cart?.items.length > 0 && cart.cart.items.every(i => i.checked))
async function load() { loading.value = true; error.value = null; try { await cart.load() } catch (e) { error.value = e } finally { loading.value = false } }
async function act(fn) { busy.value = true; try { await fn() } catch (e) { ElMessage.error(e.message); if (e.status === 409 || e.uncertain) await load() } finally { busy.value = false } }
async function remove(item) { try { await ElMessageBox.confirm(`将「${item.propName}」从购物车移除？`, '移除道具', { confirmButtonText: '移除', cancelButtonText: '保留', type: 'warning' }); await act(() => cart.remove(item.cartItemId)) } catch { /* dialog cancelled */ } }
function goCheckout() { const ids = cart.cart.items.filter(i => i.checked && i.canCheckout).map(i => i.cartItemId); if (ids.length > 50) return ElMessage.warning('每次最多结算 50 种道具，请调整选择'); checkout.begin({ source: 'CART', cartItemIds: ids }); router.push('/checkout') }
onMounted(() => { load(); window.addEventListener('mall-demo-change', load) }); onUnmounted(() => window.removeEventListener('mall-demo-change', load))
</script>
<template><div class="container page-view"><div class="page-heading compact"><span class="eyebrow">YOUR LOOT BAG</span><h1>购物车<span class="heading-dot">.</span><small v-if="cart.cart">{{ cart.cart.summary.totalItemCount }} 件道具</small></h1><p>心仪装备已集结，准备开启下一场冒险。</p></div><StatePanel :loading="loading" :error="error" :empty="!cart.cart?.items.length" title="购物车还是空的" description="探索商城，把心仪的装备加入你的补给清单。" @retry="load"><template v-if="cart.cart"><p v-if="cart.cart.summary.invalidItemCount" class="notice warning"><Icon name="info" />有 {{ cart.cart.summary.invalidItemCount }} 件道具暂时无法结算，请调整数量或移除。</p><div class="cart-table"><div class="cart-table-head"><label><input type="checkbox" :checked="all" :disabled="busy" @change="act(() => cart.select({ cartItemIds: cart.cart.items.map(i => i.cartItemId), checked: $event.target.checked }))" />全选</label><span>道具信息</span><span>单价</span><span>数量</span><span>小计</span><span /></div><article v-for="item in cart.cart.items" :key="item.cartItemId" class="cart-row" :class="{ invalid: !item.canCheckout }"><input type="checkbox" :checked="item.checked" :disabled="busy" :aria-label="`选择${item.propName}`" @change="act(() => cart.update(item.cartItemId, { quantity: item.quantity, checked: $event.target.checked }))" /><RouterLink :to="`/props/${item.propId}`" class="cart-product"><ItemArt :src="item.coverUrl" :alt="item.propName" /><span><small>{{ item.categoryName }}</small><strong>{{ item.propName }}</strong><span v-if="!item.canCheckout" class="danger">{{ availabilityText[item.availability] }}</span><span v-else class="muted">虚拟道具 · 人工交付</span></span></RouterLink><span class="cart-unit">¥{{ money(item.unitPrice) }}</span><QuantityInput :model-value="item.quantity" :max="Math.max(item.quantity, Math.min(99, item.stock))" :disabled="busy" @update:model-value="act(() => cart.update(item.cartItemId, { quantity: $event, checked: item.checked }))" /><strong class="cart-subtotal">¥{{ money(item.subtotal) }}</strong><button class="icon-button" :disabled="busy" :aria-label="`移除${item.propName}`" @click="remove(item)"><Icon name="trash" :size="18" /></button></article></div><div class="cart-summary"><RouterLink to="/props" class="continue-shopping">← 继续挑选</RouterLink><div><p>已选 <strong>{{ cart.cart.summary.selectedQuantity }}</strong> 件道具 <span class="summary-total">合计 <strong>¥{{ money(cart.cart.summary.selectedAmount) }}</strong></span></p><small>最终价格与库存以结算页为准</small></div><button class="btn" :disabled="busy || !cart.cart.summary.selectedItemCount" @click="goCheckout">去结算<Icon name="arrow" :size="18" /></button></div></template></StatePanel></div></template>
